impl Issue {
    pub fn new(id: String, title: String, source_repo: String) -> Self {
        let now = Utc::now();
        Issue {
            id,
            title,
            source_repo: Some(source_repo),
            created_at: now,
            updated_at: now,
            status: Status::default(),
            priority: Priority::default(),  // P2 (MEDIUM)
